<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { api } from '../api/client'
import { useAccountsStore } from '../stores/accounts'
import { useSessionStore } from '../stores/session'
import { exchangeNames, type Account, type AccountInput, type AccountMode } from '../types/domain'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
const store = useAccountsStore(), session = useSessionStore()
const search = ref(''), error = ref(''), message = ref(''), busy = ref(false)
const createDialog = ref<HTMLDialogElement>(), credentialDialog = ref<HTMLDialogElement>()
const target = ref<Account | null>(null)
const form = reactive<AccountInput>({ label: '', exchange: 'binance', environment: 'DEMO', account_mode: 'STANDARD', region_profile: 'GLOBAL' })
const credentials = reactive({ api_key: '', secret: '', passphrase: '' })
const modes = computed<AccountMode[]>(() => form.exchange === 'binance' ? ['STANDARD', 'UNKNOWN'] : form.exchange === 'bitget' ? ['CLASSIC', 'UTA', 'UNKNOWN'] : ['UNIFIED', 'UNKNOWN'])
const filtered = computed(() => store.accounts.filter(a => (a.label + ' ' + exchangeNames[a.exchange]).toLowerCase().includes(search.value.toLowerCase())))
watch(() => form.exchange, () => { form.account_mode = modes.value[0] ?? 'UNKNOWN' })
onMounted(store.refresh)
function clearCredentials(): void { credentials.api_key = ''; credentials.secret = ''; credentials.passphrase = ''; target.value = null }
function openCreate(): void { error.value = ''; form.label = ''; createDialog.value?.showModal() }
async function create(): Promise<void> { busy.value = true; error.value = ''; try { await store.create(form); createDialog.value?.close(); message.value = '账户配置已保存，尚未连接交易所' } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存失败' } finally { busy.value = false } }
async function openCredentials(account: Account): Promise<void> { clearCredentials(); target.value = account; error.value = ''; await nextTick(); credentialDialog.value?.showModal() }
async function saveCredentials(): Promise<void> {
  if (!target.value) return
  busy.value = true; error.value = ''
  try { await api('/accounts/' + target.value.id + '/credentials', { method: 'POST', body: JSON.stringify({ api_key: credentials.api_key, secret: credentials.secret, ...(credentials.passphrase ? { passphrase: credentials.passphrase } : {}) }) }); clearCredentials(); credentialDialog.value?.close(); message.value = '密钥已加密保存；尚未验证权限或连接交易所'; await store.refresh() }
  catch (cause) { error.value = cause instanceof Error ? cause.message : '密钥保存失败' }
  finally { busy.value = false }
}
async function archive(account: Account): Promise<void> { if (!window.confirm('归档“' + account.label + '”？历史审计记录会保留。')) return; error.value = ''; try { await store.archive(account.id); message.value = '账户连接已归档' } catch (cause) { error.value = cause instanceof Error ? cause.message : '归档失败' } }
</script>
<template><div class="page-heading"><div><span class="eyebrow">EXCHANGE CONNECTIONS</span><h1>账户连接</h1><p>集中管理交易所配置，密钥仅在后端加密存储。</p></div><button v-if="session.isAdmin" class="button primary" @click="openCreate"><Icon name="plus" :size="16" />添加账户</button></div><div v-if="message" class="alert success" role="status">{{ message }}</div><div v-if="store.error || (error && !createDialog?.open && !credentialDialog?.open)" class="alert error" role="alert">{{ store.error || error }}</div><div class="notice"><Icon name="lock" /><div><strong>配置已保存，不代表连接已验证</strong><span>E01 不向交易所发送请求；真实数据同步在 E02 实现，交易执行继续锁定。</span></div></div><section class="panel"><div class="panel-heading"><h2>连接列表 <span class="count-tag">{{ store.accounts.length }}</span></h2><input v-model="search" class="search-input" type="search" placeholder="搜索账户或交易所" aria-label="搜索账户或交易所"></div><div v-if="store.loading" class="loading-state" role="status">正在读取账户配置…</div><EmptyState v-else-if="!store.accounts.length" title="添加你的第一个交易所账户" description="先选择交易所、模拟或实盘，再配置对应的账户模式。" icon="link"><button v-if="session.isAdmin" class="button secondary" @click="openCreate">添加账户连接</button></EmptyState><div v-else class="table-scroll"><table><thead><tr><th>账户 / 交易所</th><th>环境</th><th>账户模式</th><th>密钥状态</th><th>同步状态</th><th>操作</th></tr></thead><tbody><tr v-for="account in filtered" :key="account.id"><td><strong>{{ account.label }}</strong><small>{{ exchangeNames[account.exchange] }} · {{ account.region_profile }}</small></td><td><span class="pill" :class="account.environment === 'LIVE' ? 'amber-pill' : 'blue-pill'">{{ account.environment === 'LIVE' ? 'LIVE 实盘' : 'DEMO 模拟' }}</span></td><td class="mono">{{ account.account_mode }}</td><td><span :class="account.credentials_configured ? 'positive' : 'muted'">{{ account.credentials_configured ? '已加密保存' : '未配置' }}</span><small v-if="account.credential_version">版本 {{ account.credential_version }}</small></td><td><span class="pill muted-pill">未验证</span></td><td><div v-if="session.isAdmin" class="table-actions"><button class="text-button" @click="openCredentials(account)">{{ account.credentials_configured ? '更新密钥' : '配置密钥' }}</button><button class="text-button muted" @click="archive(account)">归档</button></div><span v-else class="muted">只读</span></td></tr><tr v-if="!filtered.length"><td colspan="6" class="center muted">没有匹配的账户</td></tr></tbody></table></div></section>
<dialog ref="createDialog" class="modal"><form @submit.prevent="create"><div class="modal-heading"><div><span class="eyebrow">NEW CONNECTION</span><h2>添加账户连接</h2></div><button type="button" class="icon-button" aria-label="关闭" @click="createDialog?.close()">×</button></div><div v-if="error" class="alert error" role="alert">{{ error }}</div><label>账户名称<input v-model="form.label" required maxlength="80" placeholder="例如：主账户 · 模拟"></label><div class="form-grid"><label>交易所<select v-model="form.exchange"><option value="binance">Binance</option><option value="bitget">Bitget</option><option value="okx">OKX 欧易</option></select></label><label>环境<select v-model="form.environment"><option value="DEMO">DEMO 模拟</option><option value="LIVE">LIVE 实盘</option></select></label></div><div class="form-grid"><label>账户模式<select v-model="form.account_mode"><option v-for="mode in modes" :key="mode" :value="mode">{{ mode }}</option></select></label><label>地区配置标识<input v-model="form.region_profile" required maxlength="32" pattern="[A-Za-z0-9_-]+"></label></div><p class="fine-print">当前只保存配置。请按实际账户选择环境和模式；不会自动切换交易所设置。</p><div class="modal-actions"><button type="button" class="button secondary" @click="createDialog?.close()">取消</button><button class="button primary" :disabled="busy">{{ busy ? '保存中…' : '保存配置' }}</button></div></form></dialog>
<dialog ref="credentialDialog" class="modal" @close="clearCredentials"><form @submit.prevent="saveCredentials"><div class="modal-heading"><div><span class="eyebrow">ENCRYPTED CREDENTIALS</span><h2>{{ target?.label }} · 密钥配置</h2></div><button type="button" class="icon-button" aria-label="关闭" @click="credentialDialog?.close()">×</button></div><div v-if="error" class="alert error" role="alert">{{ error }}</div><label>API Key<input v-model="credentials.api_key" type="password" autocomplete="off" required maxlength="2048"></label><label>Secret<input v-model="credentials.secret" type="password" autocomplete="new-password" required maxlength="8192"></label><label v-if="target?.exchange !== 'binance'">Passphrase<input v-model="credentials.passphrase" type="password" autocomplete="new-password" required maxlength="2048"></label><p class="fine-print">建议仅提供只读权限。DEMO 使用对应模拟密钥；后端不会回传已保存的密钥。</p><div class="modal-actions"><button type="button" class="button secondary" @click="credentialDialog?.close()">取消</button><button class="button primary" :disabled="busy">{{ busy ? '加密保存中…' : '加密保存' }}</button></div></form></dialog></template>
